export default function UCMPage() {
  const [asked, setAsked] = useState<string | null>(null);

  return (
    <div
      style={{
        background: colours.bg,
        minHeight: "100vh",
        padding: "32px 20px",
        fontFamily: "'Inter', 'Segoe UI', system-ui, sans-serif",
        color: colours.text,
        maxWidth: 780,
        margin: "0 auto",
      }}
    >
      {/* ── PAGE HEADER ── */}
      <div style={{ marginBottom: 32 }}>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
          <Chip label="Classical Mechanics" color={colours.accent} />
          <Chip label="Kinematics" color={colours.cyan} />
          <Chip label="Grade 11–12 Physics" color={colours.purple} />
        </div>
        <h1 style={{ fontSize: 32, fontWeight: 800, margin: 0, lineHeight: 1.2, letterSpacing: "-0.02em" }}>
          Uniform Circular Motion
        </h1>
        <p style={{ color: colours.textMuted, marginTop: 10, fontSize: 15, lineHeight: 1.7, maxWidth: 620 }}>
          An object moving at constant speed along a circular path — where direction changes
          continuously, producing a persistent inward acceleration.
        </p>
      </div>

      {/* ── QUICK DEFINITION ── */}
      <Card style={{ borderColor: `${colours.accent}40`, background: `linear-gradient(135deg, ${colours.surface}, ${colours.accent}08)` }}>
        <SectionLabel text="Quick Definition" color={colours.accent} />
        <p style={{ margin: 0, fontSize: 15, lineHeight: 1.8, color: colours.text }}>
          <strong style={{ color: colours.accent }}>Uniform Circular Motion (UCM)</strong> is motion
          along a circular path where the <em>speed remains constant</em> but the{" "}
          <em>velocity vector continuously changes direction</em>. Because velocity changes, there
          must be a non-zero acceleration — always directed toward the centre of the circle.
        </p>
      </Card>

      {/* ── KEY INSIGHT CALLOUTS ── */}
      <Callout icon="⚡" title="Speed ≠ Velocity" color={colours.amber}>
        In UCM, speed (magnitude) is constant. But velocity is a vector — its direction rotates
        every instant. A changing velocity means acceleration exists even at constant speed.
      </Callout>

      <Callout icon="🎯" title="The Centripetal Direction" color={colours.cyan}>
        Centripetal means <em>"centre-seeking"</em>. The acceleration always points from the
        object <strong>toward the centre</strong> of the circular path — perpendicular to the
        velocity at every point.
      </Callout>

      {/* ── FORMULA 1: Centripetal Acceleration ── */}
      <FormulaCard
        title="Formula — Centripetal Acceleration"
        tex={String.raw`a_c = \frac{v^2}{r}`}
        accentColor={colours.accent}
        explain={[
          { sym: "a_c", meaning: "Centripetal acceleration — directed toward the centre", unit: "m/s²" },
          { sym: "v", meaning: "Speed of the object along the circular path", unit: "m/s" },
          { sym: "r", meaning: "Radius of the circular path", unit: "m" },
        ]}
        labData={{
          title: "Centripetal Acceleration",
          tex: String.raw`a_c = \frac{v^2}{r}`,
          variables: [
            { sym: "v", name: "Speed", unit: "m/s", default: 10, min: 1, max: 50, step: 0.5 },
            { sym: "r", name: "Radius", unit: "m", default: 5, min: 0.5, max: 100, step: 0.5 },
          ],
          derive: (vals) => ({
            label: "Centripetal Acceleration aₒ",
            value: `${(vals.v ** 2 / vals.r).toFixed(3)} m/s²`,
          }),
        }}
      />

      {/* ── FORMULA 2: Centripetal Force ── */}
      <FormulaCard
        title="Formula — Centripetal Force"
        tex={String.raw`F_c = \frac{mv^2}{r}`}
        accentColor={colours.green}
        explain={[
          { sym: "F_c", meaning: "Net centripetal force — directed toward the centre", unit: "N" },
          { sym: "m", meaning: "Mass of the object", unit: "kg" },
          { sym: "v", meaning: "Speed of the object", unit: "m/s" },
          { sym: "r", meaning: "Radius of the circular path", unit: "m" },
        ]}
        labData={{
          title: "Centripetal Force",
          tex: String.raw`F_c = \frac{mv^2}{r}`,
          variables: [
            { sym: "m", name: "Mass", unit: "kg", default: 2, min: 0.1, max: 100, step: 0.1 },
            { sym: "v", name: "Speed", unit: "m/s", default: 10, min: 1, max: 50, step: 0.5 },
            { sym: "r", name: "Radius", unit: "m", default: 5, min: 0.5, max: 100, step: 0.5 },
          ],
          derive: (vals) => ({
            label: "Centripetal Force Fₒ",
            value: `${((vals.m * vals.v ** 2) / vals.r).toFixed(3)} N`,
          }),
        }}
      />

      {/* ── FORMULA 3: Period ── */}
      <FormulaCard
        title="Formula — Period of Revolution"
        tex={String.raw`T = \frac{2\pi r}{v}`}
        accentColor={colours.cyan}
        explain={[
          { sym: "T", meaning: "Period — time for one complete revolution", unit: "s" },
          { sym: "r", meaning: "Radius of the circular path", unit: "m" },
          { sym: "v", meaning: "Speed of the object", unit: "m/s" },
          { sym: "2\\pi r", meaning: "Circumference of the circle (full path length)", unit: "m" },
        ]}
        labData={{
          title: "Period of Revolution",
          tex: String.raw`T = \frac{2\pi r}{v}`,
          variables: [
            { sym: "r", name: "Radius", unit: "m", default: 5, min: 0.5, max: 200, step: 0.5 },
            { sym: "v", name: "Speed", unit: "m/s", default: 10, min: 0.5, max: 100, step: 0.5 },
          ],
          derive: (vals) => ({
            label: "Period T",
            value: `${((2 * Math.PI * vals.r) / vals.v).toFixed(4)} s`,
          }),
        }}
      />

      {/* ── COMPARISON TABLE ── */}
      <CompareTable />

      {/* ── IMPORTANT NOTE ── */}
      <Callout icon="🚫" title="Common Misconception — Centrifugal Force" color={colours.red}>
        There is <strong>no outward centrifugal force</strong> in an inertial frame. What you feel
        being "pushed outward" in a turning car is simply your inertia resisting the inward
        centripetal force. Centrifugal force is a <em>fictitious force</em> that appears only in
        rotating (non-inertial) reference frames.
      </Callout>

      {/* ── APPLICATIONS ── */}
      <ApplicationsGrid />

      {/* ── SUMMARY ── */}
      <Card style={{ borderColor: `${colours.amber}40` }}>
        <SectionLabel text="Summary" color={colours.amber} />
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {[
            ["Speed", "Constant — magnitude of velocity never changes"],
            ["Velocity", "Continuously changing direction — tangent to the circle"],
            ["Acceleration", "Centripetal — always directed toward the centre"],
            ["Force", "A real net force must act inward to maintain circular motion"],
            ["Energy", "Kinetic energy is constant (speed is constant)"],
          ].map(([term, desc]) => (
            <div
              key={term}
              style={{
                display: "flex",
                gap: 12,
                alignItems: "flex-start",
                padding: "10px 14px",
