                                    <td>Velocity</td>
                                    <td>m/s</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <!-- Applications Card -->
            <div class="card">
                <div class="card-header">
                    <div class="card-icon">🚀</div>
                    <div class="card-title">Applications</div>
                </div>
