        </p>
        <div className="bg-white rounded-xl border border-purple-100 px-4 py-4 text-center shadow-inner">
          <DisplayMath latex="R = \frac{V}{I}" />
        </div>
        <div className="mt-3 grid grid-cols-3 gap-2 text-center text-xs">
          {[
            { label: "SI Unit", value: "Ohm (Ω)" },
            { label: "Dimension", value: "[ML²T⁻³A⁻²]" },
            { label: "Nature", value: "Scalar quantity" },
          ].map((item, i) => (
            <div key={i} className="bg-purple-100 rounded-lg py-2 px-1">
              <p className="text-purple-600 font-semibold">{item.label}</p>
              <p className="text-gray-700 mt-0.5 font-bold">{item.value}</p>
            </div>
          ))}
        </div>
      </SectionCard>

      {/* V-I Graph */}
      <SectionCard icon="📈" title="V-I Characteristic Graph" color="blue">
        <div className="bg-white rounded-xl border border-blue-100 p-4 shadow-inner">
          {/* Simple ASCII-style SVG Graph */}
          <svg viewBox="0 0 260 200" className="w-full max-w-xs mx-auto block">
            {/* Grid lines */}
            {[40, 80, 120, 160].map((y) => (
              <line key={y} x1="40" y1={y} x2="240" y2={y} stroke="#e0e7ff" strokeWidth="1" />
            ))}
            {[80, 120, 160, 200].map((x) => (
              <line key={x} x1={x} y1="20" x2={x} y2="170" stroke="#e0e7ff" strokeWidth="1" />
