            {/* Axes */}
            <line x1="40" y1="170" x2="240" y2="170" stroke="#374151" strokeWidth="2" />
            <line x1="40" y1="170" x2="40" y2="20" stroke="#374151" strokeWidth="2" />
            {/* Ohmic line */}
            <line x1="40" y1="170" x2="220" y2="30" stroke="#2563eb" strokeWidth="2.5" strokeLinecap="round" />
