      {/* Exam Tip */}
      <div className="rounded-2xl border border-amber-200 bg-gradient-to-br from-amber-50 to-yellow-50 shadow-md px-5 py-4 my-4">
        <div className="flex items-start gap-3">
          <span className="text-2xl">🎯</span>
