                                    <td>$f$</td>
                                    <td>$f \times \sqrt{2}$</td>
                                </tr>
                                <tr>
                                    <td>Visual Speed</td>
                                    <td>Normal</td>
                                    <td>Faster (~1.41x)</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </article>

