// ══════════════════════════════════════════════════════
function FormulaLab({ formula, title, variables, description }) {
  const [open, setOpen] = useState(false);
  const [vals, setVals] = useState(
    Object.fromEntries(variables.map((v) => [v.key, v.default]))
  );

  const result = formula.compute(vals);

  return (
    <div style={{ marginTop: 12 }}>
      <button
        onClick={() => setOpen((o) => !o)}
        style={{
          background: open ? C.accentSoft : C.surface,
          color: open ? C.accentText : C.textSecondary,
          border: `1px solid ${open ? C.accent : C.divider}`,
          borderRadius: 8,
          padding: "7px 18px",
          fontSize: 12,
          cursor: "pointer",
          fontWeight: 600,
          marginRight: 8,
        }}
      >
        {open ? "▼ Close Formula Lab" : "⚗ Open Formula Lab"}
      </button>

      {open && (
        <div
          style={{
            marginTop: 14,
            background: C.surface,
            border: `1px solid ${C.accent}`,
            borderRadius: 12,
            padding: "18px 20px",
          }}
        >
          <div style={{ fontSize: 12, fontWeight: 700, color: C.accentText, marginBottom: 12, letterSpacing: "0.08em" }}>
            ⚗ {title} — Interactive Lab
          </div>
          <div style={{ fontSize: 12, color: C.textSecondary, marginBottom: 14 }}>{description}</div>

          {variables.map((v) => (
            <div key={v.key} style={{ marginBottom: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                <span style={{ fontSize: 12, color: C.textSecondary }}>
                  <KT tex={v.label} /> — {v.name}
                </span>
                <span style={{ fontSize: 12, color: C.accentText, fontWeight: 700 }}>
                  {vals[v.key].toFixed(v.decimals ?? 2)} {v.unit}
                </span>
              </div>
              <input
                type="range"
                min={v.min} max={v.max} step={v.step}
                value={vals[v.key]}
                onChange={(e) => setVals({ ...vals, [v.key]: parseFloat(e.target.value) })}
                style={{ width: "100%", accentColor: C.accent }}
              />
            </div>
          ))}

          <div
            style={{
              background: C.card,
              border: `1px solid ${C.teal}`,
              borderRadius: 10,
              padding: "12px 16px",
              marginTop: 8,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <span style={{ fontSize: 12, color: C.textSecondary }}>Result</span>
            <span style={{ fontSize: 16, color: C.teal, fontWeight: 700 }}>
              {result.value.toFixed(result.decimals ?? 2)} {result.unit}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

