// KEPLER CARD
// ══════════════════════════════════════════════════════
function KeplerCard() {
  const [step, setStep] = useState(0);
  const steps = [
    {
      title: "Circular Speed Condition",
      content: "At circular orbital speed, gravity exactly provides the centripetal force needed. The planet neither falls inward nor drifts outward.",
      tex: "\\frac{mv_c^2}{r} = \\frac{GMm}{r^2}",
      color: C.green,
    },
    {
      title: "Below Circular Speed",
      content: "When velocity drops below v_c, gravity exceeds the centripetal requirement. The net inward force pulls the planet below the original circular path.",
      tex: "\\frac{mv^2}{r} < \\frac{GMm}{r^2} \\quad \\Rightarrow \\quad F_{\\text{net inward}} > 0",
      color: C.amber,
    },
    {
      title: "Elliptical Orbit Forms",
      content: "The planet traces an ellipse with the star at one focus. The point of velocity reduction becomes the apoapsis — the farthest point from the star.",
      tex: "r_{\\text{apo}} = r_0 \\quad (\\text{where } v \\text{ was reduced})",
      color: C.accent,
    },
    {
      title: "Conservation of Energy",
      content: "Total mechanical energy is conserved. The planet gains speed at periapsis and slows at apoapsis — exactly as Kepler's second law demands.",
      tex: "E = \\frac{1}{2}mv^2 - \\frac{GMm}{r} = \\text{const}",
      color: C.teal,
    },
  ];

  return (
    <Card accent={steps[step].color}>
      <SectionLabel icon="📖" text="Step-by-Step Reasoning" color={C.textSecondary} />

      {/* Step tabs */}
      <div style={{ display: "flex", gap: 6, marginBottom: 18, flexWrap: "wrap" }}>
        {steps.map((s, i) => (
          <button
            key={i}
            onClick={() => setStep(i)}
            style={{
              background: step === i ? s.color + "22" : C.surface,
              color: step === i ? s.color : C.textMuted,
              border: `1px solid ${step === i ? s.color : C.divider}`,
              borderRadius: 8,
              padding: "5px 14px",
              fontSize: 11,
              fontWeight: 700,
              cursor: "pointer",
            }}
          >
            {i + 1}. {s.title.split(" ").slice(0, 2).join(" ")}
          </button>
        ))}
      </div>

      <div
        style={{
          background: C.bg,
          borderRadius: 10,
          padding: "16px 18px",
          border: `1px solid ${steps[step].color}44`,
        }}
      >
        <div style={{ fontSize: 13, fontWeight: 700, color: steps[step].color, marginBottom: 8 }}>
          {steps[step].title}
        </div>
        <div style={{ fontSize: 13, color: C.textSecondary, lineHeight: 1.7, marginBottom: 14 }}>
          {steps[step].content}
        </div>
        <div style={{ textAlign: "center", fontSize: 17 }}>
          <KT tex={steps[step].tex} block />
        </div>
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 14 }}>
        <button
          onClick={() => setStep((s) => Math.max(0, s - 1))}
          disabled={step === 0}
          style={{
            background: C.surface, color: step === 0 ? C.textMuted : C.textSecondary,
            border: `1px solid ${C.divider}`, borderRadius: 8, padding: "6px 16px",
            fontSize: 12, cursor: step === 0 ? "default" : "pointer",
          }}
        >
          ← Previous
        </button>
        <span style={{ fontSize: 11, color: C.textMuted, alignSelf: "center" }}>
          {step + 1} / {steps.length}
        </span>
        <button
          onClick={() => setStep((s) => Math.min(steps.length - 1, s + 1))}
          disabled={step === steps.length - 1}
          style={{
            background: step === steps.length - 1 ? C.surface : C.accentSoft,
            color: step === steps.length - 1 ? C.textMuted : C.accentText,
            border: `1px solid ${step === steps.length - 1 ? C.divider : C.accent}`,
            borderRadius: 8, padding: "6px 16px", fontSize: 12,
            cursor: step === steps.length - 1 ? "default" : "pointer",
          }}
        >
          Next →
        </button>
      </div>
    </Card>
  );
}

