// FORMULA DATA
// ============================================================
const FORMULAS: FormulaData[] = [
  {
    id: "restitution",
    title: "Coefficient of Restitution",
    latex: "e = \\frac{v_2' - v_1'}{v_1 - v_2}",
    variables: [
      { symbol: "e", description: "Coefficient of restitution", range: "0 ≤ e ≤ 1" },
      { symbol: "v₁", description: "Initial velocity of body 1", range: "m/s" },
      { symbol: "v₂", description: "Initial velocity of body 2", range: "m/s" },
      { symbol: "v₁'", description: "Final velocity of body 1", range: "m/s" },
      { symbol: "v₂'", description: "Final velocity of body 2", range: "m/s" },
    ],
    context: "Defines the ratio of relative separation speed to relative approach speed after collision.",
  },
  {
    id: "momentum",
    title: "Conservation of Momentum",
    latex: "m_1 v_1 + m_2 v_2 = m_1 v_1' + m_2 v_2'",
    variables: [
      { symbol: "m₁, m₂", description: "Masses of the two bodies", range: "kg" },
      { symbol: "v₁, v₂", description: "Pre-collision velocities", range: "m/s" },
      { symbol: "v₁', v₂'", description: "Post-collision velocities", range: "m/s" },
    ],
    context: "Total momentum is always conserved regardless of the restitution value.",
  },
  {
    id: "postcollision",
    title: "Post-Collision Velocities",
    latex: "v_1' = \\frac{m_1 v_1 + m_2 v_2 - m_2 e(v_1 - v_2)}{m_1 + m_2}",
