// ============================================================
// KATEX RENDERER
// ============================================================
declare global {
  interface Window {
    katex: {
      renderToString: (latex: string, opts: object) => string;
    };
  }
}

function KaTeX({ latex, display = false }: { latex: string; display?: boolean }) {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const render = () => {
      if (ref.current && window.katex) {
        try {
          ref.current.innerHTML = window.katex.renderToString(latex, {
            displayMode: display,
            throwOnError: false,
          });
        } catch {}
      }
    };
    if (window.katex) {
      render();
    } else {
      const interval = setInterval(() => {
        if (window.katex) {
          clearInterval(interval);
          render();
        }
      }, 100);
      return () => clearInterval(interval);
    }
  }, [latex, display]);
  return <span ref={ref} />;
}

