// ============================================================
// POST COLLISION LAB
// ============================================================
function PostCollisionLab() {
  const [m1, setM1] = useState(2);
  const [m2, setM2] = useState(2);
  const [v1, setV1] = useState(8);
  const [v2, setV2] = useState(-3);
  const [e, setE] = useState(0.8);

  const totalM = m1 + m2;
  const pBefore = m1 * v1 + m2 * v2;
  const v1f = (m1 * v1 + m2 * v2 - m2 * e * (v1 - v2)) / totalM;
  const v2f = (m1 * v1 + m2 * v2 + m1 * e * (v1 - v2)) / totalM;
  const keBefore = 0.5 * m1 * v1 ** 2 + 0.5 * m2 * v2 ** 2;
  const keAfter = 0.5 * m1 * v1f ** 2 + 0.5 * m2 * v2f ** 2;
  const keLoss = keBefore - keAfter;

  return (
    <div className="px-5 py-4 bg-violet-50">
      <p className="text-xs font-semibold text-violet-500 uppercase tracking-wider mb-4">
        Formula Lab — Post-Collision Velocities
      </p>
      <div className="grid grid-cols-2 gap-3 mb-4">
        {[
          { label: "m₁ (kg)", val: m1, set: setM1, min: 0.5, max: 10, step: 0.5 },
          { label: "m₂ (kg)", val: m2, set: setM2, min: 0.5, max: 10, step: 0.5 },
          { label: "v₁ (m/s)", val: v1, set: setV1, min: -15, max: 15, step: 1 },
          { label: "v₂ (m/s)", val: v2, set: setV2, min: -15, max: 15, step: 1 },
          { label: "e (restitution)", val: e, set: setE, min: 0, max: 1, step: 0.01 },
        ].map((item) => (
          <div key={item.label} className="flex flex-col gap-1">
            <label className="text-xs text-violet-600 font-medium">{item.label}</label>
            <input
              type="range"
              min={item.min}
              max={item.max}
              step={item.step}
              value={item.val}
              onChange={(ev) => item.set(Number(ev.target.value))}
              className="accent-violet-500"
            />
            <span className="text-xs text-center text-slate-600 font-mono">{item.val}</span>
          </div>
        ))}
      </div>
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-white rounded-lg p-3 border border-violet-200 text-center">
          <p className="text-xs text-slate-400">v₁' (Body 1 after)</p>
          <p className="text-lg font-bold text-indigo-600 font-mono">{v1f.toFixed(2)} m/s</p>
        </div>
        <div className="bg-white rounded-lg p-3 border border-violet-200 text-center">
          <p className="text-xs text-slate-400">v₂' (Body 2 after)</p>
          <p className="text-lg font-bold text-indigo-600 font-mono">{v2f.toFixed(2)} m/s</p>
        </div>
        <div className="bg-white rounded-lg p-3 border border-violet-200 text-center">
          <p className="text-xs text-slate-400">Momentum (conserved)</p>
          <p className="text-sm font-bold text-green-600 font-mono">{pBefore.toFixed(2)} kg·m/s</p>
        </div>
        <div className="bg-white rounded-lg p-3 border border-violet-200 text-center">
          <p className="text-xs text-slate-400">KE lost</p>
          <p className="text-sm font-bold text-orange-500 font-mono">{keLoss.toFixed(2)} J</p>
        </div>
      </div>
    </div>
  );
}

