          <span style={{ background: region.color, borderRadius: 6, padding: "2px 10px", color: "#fff", fontWeight: 700, fontSize: 12 }}>{region.label}</span>
          <span style={{ color: "#94a3b8", fontSize: 13 }}>{region.desc}</span>
        </div>

        {/* Wave Viz */}
        <div style={{ background: "#0a0f1e", borderRadius: 12, padding: 12, marginBottom: 12, border: "1px solid #1e293b" }}>
