          <AnimatedWave omega={omega} omega0={omega0} gamma={gamma} playing={playing} />
        </div>

        {/* Amplitude Curve */}
        <div style={{ background: "#0a0f1e", borderRadius: 12, padding: 12, marginBottom: 20, border: "1px solid #1e293b" }}>
          <div style={{ color: "#475569", fontSize: 11, marginBottom: 6, fontWeight: 600, textTransform: "uppercase", letterSpacing: 1 }}>Amplitude vs Frequency — Current Position ●</div>
          <AmplitudeCurve omega={omega} omega0={omega0} gamma={gamma} />
        </div>

        {/* Metrics */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 20 }}>
          {[
            { label: "ω / ω₀", value: ratio.toFixed(2), color: region.color },
            { label: "Amplitude", value: Anorm.toFixed(3), color: "#e2e8f0" },
            { label: "Damping γ", value: gamma.toFixed(2), color: "#94a3b8" },
