            {playing ? "⏸ Pause" : "▶ Play"}
          </button>
          <button
            onClick={() => { setOmega(omega0); }}
            style={{ background: "#1e293b", border: "1px solid #f59e0b44", borderRadius: 8, color: "#f59e0b", padding: "8px 18px", cursor: "pointer", fontWeight: 600, fontSize: 13 }}
          >
            Set ω = ω₀ (Resonance)
          </button>
        </div>
      </div>
    </div>
  );
};

