function FormulaLab({ data }: { data: FormulaData }) {
  const [inputs, setInputs] = useState<Record<string, number>>({
    m1: 2.0,
    m2: 0.5,
    v0: 4.2,
    L: 1.5,
  });

  const momentum = inputs.m1 * inputs.v0;
  const vFinal = momentum / (inputs.m1 + inputs.m2);
  const ke_before = 0.5 * inputs.m1 * inputs.v0 ** 2;
  const ke_after = 0.5 * (inputs.m1 + inputs.m2) * vFinal ** 2;
  const keLost = ke_before - ke_after;
  const maxAngle =
    (Math.acos(1 - (vFinal ** 2) / (2 * G * inputs.L)) * 180) / Math.PI;

  return (
    <div className="lab-panel">
      <div className="lab-header">
        <span>⚗</span>
        <span>Formula Lab — Collision Dynamics</span>
      </div>

      <div className="lab-inputs">
        {[
          { key: "m1", label: "Bob Mass (kg)", min: 0.1, max: 10, step: 0.1 },
          {
            key: "m2",
            label: "Object Mass (kg)",
            min: 0.1,
            max: 10,
            step: 0.1,
          },
          {
            key: "v0",
            label: "Impact Velocity (m/s)",
            min: 0.1,
            max: 20,
            step: 0.1,
          },
          { key: "L", label: "String Length (m)", min: 0.5, max: 5, step: 0.1 },
        ].map(({ key, label, min, max, step }) => (
          <div key={key} className="lab-input-row">
            <label>{label}</label>
            <input
              type="range"
              min={min}
              max={max}
              step={step}
              value={inputs[key]}
              onChange={(e) =>
                setInputs((p) => ({ ...p, [key]: parseFloat(e.target.value) }))
              }
            />
            <span className="lab-value">{inputs[key].toFixed(2)}</span>
          </div>
        ))}
      </div>

      <div className="lab-results">
        <div className="lab-result-row">
          <span>Final Velocity</span>
          <span className="result-val">{vFinal.toFixed(3)} m/s</span>
        </div>
        <div className="lab-result-row">
          <span>KE Before</span>
          <span className="result-val">{ke_before.toFixed(3)} J</span>
        </div>
        <div className="lab-result-row">
          <span>KE After</span>
          <span className="result-val">{ke_after.toFixed(3)} J</span>
        </div>
        <div className="lab-result-row highlight">
          <span>KE Lost (Heat/Sound)</span>
          <span className="result-val">{keLost.toFixed(3)} J</span>
        </div>
        <div className="lab-result-row highlight">
          <span>Max Swing Angle</span>
          <span className="result-val">
            {isNaN(maxAngle) ? "—" : maxAngle.toFixed(1) + "°"}
          </span>
        </div>
      </div>
    </div>
  );
}

// ============================================================
// TABLE CARD
// ============================================================

function TableCard({
  title,
  headers,
  rows,
}: {
  title: string;
  headers: string[];
  rows: string[][];
}) {
  return (
    <div className="table-card">
      <div className="table-card-header">{title}</div>
      <div className="table-scroll">
        <table>
          <thead>
            <tr>
              {headers.map((h) => (
                <th key={h}>{h}</th>
              ))}
            </tr>
