function LiveTelemetry({ state }: { state: PendulumState }) {
  const speed = Math.hypot(state.velocity.x, state.velocity.y);
  const angleDeg = (state.angle * 180) / Math.PI;

  const metrics = [
    { label: "Angle", value: angleDeg.toFixed(1), unit: "°", color: "#60a5fa" },
    {
      label: "Angular Vel",
      value: state.angularVelocity.toFixed(3),
      unit: "rad/s",
      color: "#34d399",
    },
    { label: "Speed", value: speed.toFixed(2), unit: "m/s", color: "#f59e0b" },
    { label: "Tension", value: state.tension.toFixed(1), unit: "N", color: "#f87171" },
    {
      label: "Flight Time",
      value: state.flightTime.toFixed(2),
      unit: "s",
      color: "#a78bfa",
    },
    {
      label: "Total Mass",
      value: (state.mass + state.attachedObjectMass).toFixed(2),
